import{_ as a,o as e,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Монолит","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/concepts/monolith.md","filePath":"wiki/dev-commit/theory/architecture/concepts/monolith.md"}'),o={name:"wiki/dev-commit/theory/architecture/concepts/monolith.md"};function r(c,t,n,s,h,d){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="монолит" tabindex="-1">Монолит <a class="header-anchor" href="#монолит" aria-label="Permalink to &quot;Монолит&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Монолитная архитектура</strong> - единая и прочная структура, в которой все компоненты приложения крепко связаны между собой</li><li>В контексте веб-приложений мы говорим о том, что клиентский и серверный код находятся внутри одного проекта</li></ul></div><h2 id="плюсы-и-минусы" tabindex="-1">Плюсы и минусы <a class="header-anchor" href="#плюсы-и-минусы" aria-label="Permalink to &quot;Плюсы и минусы&quot;">​</a></h2><h3 id="плюсы" tabindex="-1">Плюсы <a class="header-anchor" href="#плюсы" aria-label="Permalink to &quot;Плюсы&quot;">​</a></h3><ul><li>Простота и легкость разработки. Компоненты монолитной системы тесно связаны, поэтому писать и тестировать такой код сравнительно легко. Вы поддерживаете единую базу кода, и это упрощает понимание общей логики приложения</li><li>Производительность и эффективность. Поскольку все компоненты выполняются в рамках одного процесса, отпадает нужда в межпроцессном взаимодействии. То есть, более быстрое время выполнения и минимальные временные затраты</li><li>Среда совместно используемых данных. У всех компонентов есть прямой доступ к той же базе данных, что позволяет беспрепятственно обмениваться этими данными. Тем самым устраняется необходимость в сложных механизмах синхронизации</li></ul><h3 id="минусы" tabindex="-1">Минусы <a class="header-anchor" href="#минусы" aria-label="Permalink to &quot;Минусы&quot;">​</a></h3><ul><li>Масштабирование. Все приложение масштабируется как единое целое. В итоге, если дополнительные ресурсы нужны только для определенных компонентов, это может вылиться в их нерациональное использование</li><li>Привязка к одному стеку технологий. Добавление новых технологий или фреймворков чревато перепроектированием всего приложения</li><li>Производительность. Весь монолит потребляет ресурсы сервера, на котором работает (будь то выделенный сервер, виртуальная машина и что-то еще). А если у вас есть сложный продукт с множеством опций, то вся система начнет хромать, когда для работы одной из таких функций потребуются дополнительные ресурсы. Представьте себе ситуацию: пользователь загрузил большой файл, который нужно обработать. И это внезапно сказалось на процессе входа</li><li>Деплой. Любые изменения или обновления требуют повторного развертывания всего приложения, и это ведет к увеличению времени простоя и возможным сбоям</li></ul>',7)])])}const _=a(o,[["render",r]]);export{u as __pageData,_ as default};
